        uint256 _maturity
    ) external view returns (uint256);

    function getMinDebtUnitPriceAt(
        bytes32 ccy,
        uint256 maturity,
        uint256 referenceTimestamp
    ) external view returns (uint256);

    function getOrderUnitPriceRange(
        bytes32 ccy,
